def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_threat = 0
    urgent_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_threat += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    if not alive:
        return max(0.0, min(float(budget), DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    total_players = 1 + len(alive)
    slots = int(supply // WATER_REQ)
    if slots < 0:
        slots = 0

    danger = 0
    if hp <= 3:
        danger += 3
    elif hp <= 5:
        danger += 2
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2
    if slots < 1:
        danger += 3
    elif slots < total_players:
        danger += 2
    if highest_prev >= 110:
        danger += 2
    elif highest_prev >= 85:
        danger += 1
    if urgent_opp >= 2:
        danger += 1

    if slots >= 2:
        base = 28.0
    else:
        base = 44.0

    if rich_threat >= 2:
        base += 6.0
    elif rich_threat == 1:
        base += 3.0

    if prev_bids:
        if highest_prev <= 40:
            target = max(base, highest_prev + 2.0)
        elif highest_prev <= 80:
            target = max(base + 6.0, avg_prev + 4.0)
        else:
            target = max(base + 10.0, highest_prev * 0.78)
    else:
        target = base + 4.0

    if danger >= 7:
        target = max(target, min(126.0, highest_prev + 8.0 if highest_prev > 0 else 95.0))
    elif danger >= 5:
        target = max(target, min(108.0, highest_prev + 4.0 if highest_prev > 0 else 78.0))
    elif danger <= 1 and slots >= 2:
        target = min(target, 32.0)

    if budget < target:
        if hp <= 3 or no_water_days >= 2:
            target = budget
        else:
            target = min(budget, max(18.0, budget * 0.55))

    if target > budget:
        target = budget
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        # If alone, bid to ensure we get water
        return float(min(my_status['budget'], DAILY_SALARY * 0.6))

    # Read yesterday's bids from previous_trace for immediate pressure
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    pressure = 0.0
    if yesterday_bids:
        pressure = max(yesterday_bids)

    # Estimate how many water units are likely needed/available.
    # Goal: avoid no_water_days increment by securing at least WATER_REQ.
    # If supply is low, competition likely high -> bid more.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base bid: moderate, tuned to not enter Cindy's apparent high-bid loop.
    # If pressure is extremely high, we slightly increase to avoid losing to top bidder.
    base = DAILY_SALARY * (0.45 + 0.25 * supply_norm)

    # My urgency based on hp and no_water_days
    hp = float(my_status.get('hp', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    urgency = 0.0
    if hp <= 2.0:
        urgency = 0.35
    elif hp <= 4.0:
        urgency = 0.18
    else:
        urgency = 0.08

    if no_water_days >= 2:
        urgency += 0.15
    if no_water_days >= 4:
        urgency += 0.25

    # Convert yesterday pressure into an additive bump
    bump = 0.0
    if pressure >= DAILY_SALARY * 1.25:
        # Cindy-like aggressive pressure: raise some, but not to arms-race level
        bump = DAILY_SALARY * 0.10
    elif pressure >= DAILY_SALARY * 0.85:
        bump = DAILY_SALARY * 0.06
    elif pressure >= DAILY_SALARY * 0.55:
        bump = DAILY_SALARY * 0.03

    target = base * (1.0 + urgency) + bump

    # Ensure we bid at least enough to be competitive but cap to budget.
    budget = float(my_status.get('budget', 0.0))

    # Hard cap: never bid more than budget; also avoid extreme bids.
    cap = min(budget, DAILY_SALARY * 1.05)

    # If we are very low on budget, bid minimal to preserve survival
    if budget <= DAILY_SALARY * 0.25:
        return float(max(0.0, min(budget, DAILY_SALARY * 0.18)))

    # If supply is very low, slightly higher to secure WATER_REQ
    if supply < WATER_REQ + 3:
        target *= 1.12

    bid = float(min(cap, max(0.0, target)))

    # If bid is too low relative to supply competition, ensure a floor
    # (floor chosen to react to medium scenario without overpaying)
    floor_bid = DAILY_SALARY * (0.30 + 0.10 * supply_norm)
    if bid < floor_bid and budget > floor_bid:
        bid = float(min(cap, floor_bid))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    base_bid = DAILY_SALARY * 0.65 

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        base_bid = DAILY_SALARY * 1.05 
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.85

    day_factor = (day_context['day'] / EPISODE_DAYS)
    base_bid += base_bid * 0.2 * day_factor 

    yesterday_bids = []
    opponent_water_requirements = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
        opponent_water_requirements.append(opp['water_requirement'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    if highest_prev_bid > DAILY_SALARY * 0.7:
        base_bid = max(base_bid, highest_prev_bid + 5)
    elif highest_prev_bid > 0:
        base_bid = max(base_bid, highest_prev_bid + 1)

    min_opp_req = WATER_REQ # Default if no opponents or requirements are found
    if opponent_water_requirements:
        min_opp_req = min(opponent_water_requirements)

    supply_for_me_and_one_opponent = WATER_REQ + min_opp_req

    if day_context['supply'] < WATER_REQ:
        if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
            base_bid = max(base_bid, DAILY_SALARY * 1.2)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.75)
    elif day_context['supply'] < supply_for_me_and_one_opponent:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif day_context['supply'] >= WATER_REQ * 2 and len(alive_opponents) < 2:
        base_bid = min(base_bid, DAILY_SALARY * 0.5)

    final_bid = max(0.0, base_bid)
    final_bid = min(my_status['budget'], final_bid)

    if final_bid == 0 and my_status['budget'] > 0 and (my_status['hp'] <= 5 or my_status['no_water_days'] > 0):
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.2) 

    if final_bid == 0 and my_status['budget'] > 0 and len(alive_opponents) > 0:
         final_bid = min(my_status['budget'], 1.0) 

    return final_bid
